public class RepeatArgsValidatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n") + "\"";
    }

    static String run(String... args) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            RepeatArgsValidator.main(args);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        String usage = "usage: java RepeatArgsValidator <count> <word> [word ...]\n";
        check("3 ho", "ho\nho\nho\n", run("3", "ho"));
        check("2 hello there -- words joined", "hello there\nhello there\n", run("2", "hello", "there"));
        check("1 word", "one\n", run("1", "one"));
        check("no arguments", usage, run());
        check("only a count", usage, run("4"));
        check("count is not a number", "error: count is not a whole number: abc\n", run("abc", "hi"));
        check("count is zero", "error: count must be at least 1\n", run("0", "hi"));
        check("count is negative", "error: count must be at least 1\n", run("-2", "hi"));
        check("count is too big", "error: count must be 10 or less\n", run("11", "hi"));
        check("count of exactly 10 is allowed", 10, run("10", "x").split("\n", -1).length - 1);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

