public class RepeatArgsValidator {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("usage: java RepeatArgsValidator <count> <word> [word ...]");
            return;
        }
        int count;
        try {
            count = Integer.parseInt(args[0]);
        } catch (NumberFormatException ex) {
            System.out.println("error: count is not a whole number: " + args[0]);
            return;
        }
        if (count < 1) {
            System.out.println("error: count must be at least 1");
            return;
        }
        if (count > 10) {
            System.out.println("error: count must be 10 or less");
            return;
        }

        StringBuilder line = new StringBuilder();
        for (int i = 1; i < args.length; i++) {
            if (i > 1) {
                line.append(" ");
            }
            line.append(args[i]);
        }
        for (int i = 0; i < count; i++) {
            System.out.println(line.toString());
        }
    }
}
